/* ym2612~ - YM2612-style FM voice (one chip channel), in C.
 *
 * A real coded object, not a patch.  Since 0.17.51 the DSP core is the
 * cycle-accurate Nuked-OPN2 chip emulator (nukeykt/Nuked-OPN2 ym3438.c
 * v1.0.12, LGPL-2.1 (c) Alexey Khokholov, vendored next to this file):
 * patches are applied by writing RAW CHIP REGISTERS through the chip's
 * bus protocol, notes/pitch/gate go through register 0x28 / 0xA0-0xA4,
 * and every sample is generated by clocking the chip itself - envelope
 * generator, LFO, feedback ladder, MEM delays, DAC truncation, phase
 * generator all behave exactly like the silicon.  The GM bank
 * (ym_gm_bank.h, libOPNMIDI XG bank) stays raw chip register bytes, so
 * `gm` is now a straight register dump.
 *
 * Integration details:
 *   - chip clocked at 7670454/24 per output sample: one sample = 24
 *     OPN2_Clock calls; output = the frame-aligned direct read of
 *     channel 0's 9-bit accumulator (the DAC unit's own value), then
 *     linear-resampled to the pd rate (ratio 144*rate/clock).
 *   - register writes from message handlers are queued and applied
 *     inside the audio loop one write every 16 chip clocks (the bus
 *     needs >=1 clock between an address and a data strobe), so bursts
 *     never lose writes and never punch a hole in the audio.
 *   - level: a full-scale carrier (TL 0, EG full) lands at 255/256 on
 *     its own channel outlet; the six-channel sum can reach ~6 when
 *     every channel is driven.  There is NO output clip: the silicon
 *     has none (its 9-bit accumulators are hardware-bounded), and the
 *     console amp's clip belongs to the patch downstream - attenuate
 *     before dac~.  (0.17.82 removed the old +-1 clip, whose hard edge
 *     buzzed on dense VGM mixes - the clip sat INSIDE the object, so no
 *     external *~ attenuation could ever reach it.)
 *   - `dac` grit quantizes the output samples (the chip core has its
 *     own DAC truncation inside).
 *
 *   inlet 1 (float):    midi pitch; also messages:
 *                         alg <0-7>            operator routing (reg B0)
 *                         fb <0-7>             op1 self-feedback (reg B0)
 *                         dac <0-100>          output grit
 *                         op <1-4> <param> <v> params: mul det tl rs
 *                                              ar dr sr rr sl (raw regs)
 *                         gm <1-128>           GM Level 1 instrument preset
 *                         glide <ms>          portamento time (0 = off,
 *                                             default); `note` then sweeps
 *                                             from the previous pitch
 *                         slide <midi> [ms] [vel]
 *                                             sweep to the pitch WITHOUT
 *                                             a key event (ms omitted =
 *                                             the glide time; vel 0-127 =
 *                                             the channel's peak, gate
 *                                             untouched, omitted = the
 *                                             level stays)
 *                         note <midi> [vel]    key on; vel 0 = key off
 *                                              (release; vel scales peak)
 *                         gate <0/1>
 *                         list <midi> <vel>    pitch + velocity
 *                         reg <a> <d>          raw register write (ch1
 *                                              compat path)
 *   Every voice message also takes a chN-prefixed spelling that
 *   addresses chip channel N directly - each channel is its own voice
 *   (own fnum, gate, peak, op shadows, gm preset):
 *                         chN note <midi> [vel] / chN gate <0/1>
 *                         chN alg / chN fb / chN op ... / chN gm <1-128>
 *                         chN reg <a> <d>      channel-addressed raw
 *                                              register write (regs
 *                                              0x30..0xb4 mirror per
 *                                              channel, key-on rides
 *                                              port A as on silicon)
 *                         chN dac/raw/bank     accepted, object-global
 *   Bare spellings always mean channel 1.
 *   inlet 2 (float):    gate, 1 = key-on, 0 = release; applies to the
 *                       channel of the most recent voice message (ch1
 *                       if none has been addressed yet)
 *   outlets (signal):   0 = all six chip channels summed (the chip mix),
 *                       1..6 = channels 1..6 alone (each channel its
 *                       own voice once addressed; raw mode fills all
 *                       six per the vgm writes; unused channels stay 0)
 *
 * Defaults: alg 0, fb 0, mul 1, det 0, tl op1-3 = 16 / op4 = 0,
 * ar 31, dr 12, sl 8, sr 5, rr 8, rs 0, dac 0, peak 1 (vel 127).
 */

#include "m_pd.h"
#include <math.h>
#include <string.h>
#include "ym3438.h"             /* Nuked-OPN2, LGPL-2.1 (c) Nuke.YKT */
#include "ym_gm_bank.h"

#ifndef OUTSCALE
/* channel 0's own 9-bit accumulator ch_out[-256..255] IS the channel's
 * output (the value the silicon's DAC unit consumes); full-scale carrier
 * lands at 255/256 */
#define OUTSCALE (1.0f / 256.0f)
#endif

#define CHIP_CLOCK 7670454.0                    /* NTSC YM2612 master clock */
#ifndef YMWCD
#define YMWCD 16                /* chip clocks between queued register writes */
#endif
#define CHIP_RATE  (CHIP_CLOCK / 144.0)         /* 53267.04 native rate */

/* register write queue: entries are bus strobes (port, data), applied
 * one every 16 chip clocks inside the audio loop.  16 is the floor that
 * still commits: a write lands when the chip's internal scan hits the
 * addressed slot/channel (worst ~12 clocks after the data strobe), and
 * the NEXT address strobe cancels an uncommitted write - verified by a
 * zero-crossing frequency test over all 24 write phases */
#define YMWQ 512                /* entries = 256 register writes */

typedef struct _ym {
    t_object  obj;
    t_outlet *x_out[7];  /* 0 = chip mix, 1..6 = channels 1..6 */
    t_sample *x_outv[7]; /* dsp: outlet signal vectors, refreshed by dsp()
                          * - passed to dsp_add as ONE pointer (the old
                          * 3-arg shape) so the arg count can never drift
                          * from the perform routine again */
    t_inlet *x_gatein;
    float     x_sr;
    /* per-channel voice state: bare messages are channel 0 (ch1, the
     * note/GM voice), `chN <sub>` addresses channels 1..5 directly.
     * All six share one chip, so "voice" = the channel's own fnum pair,
     * key-on bit, op shadows and gate/peak multiplier. */
    float     x_pitch[6];
    float     x_freq[6];   /* base Hz (mul 1), cached on pitch change */
    float     x_tr[6];     /* gm preset transpose (semitones) */
    float     x_peak[6];   /* velocity 0..1 */
    int       x_gate[6];
    float     x_ggain[6];  /* smoothed channel gate 0..1 */
    float     x_dac;       /* 0..1 output grit (global) */
    int       x_alg[6], x_fb[6]; /* shadow of reg B0 */
    int       x_fnum[6], x_blk[6];  /* current pitch, chip domain */
    int       x_rawmode;   /* vgm player mode: pin gate/peak, take reg writes */
    int       x_keyed;     /* a key-on reached ANY channel; before that the
                              * reset chip is provably silent (render skip) */
    int       x_voiced[6]; /* channel's instrument registers written to the
                           * chip yet?  ch1 at creation; 2-6 lazily on
                           * first voice use - raw patches depend on the
                           * reset register values, so nothing may touch
                           * channels 2-6 before they become voices */
    int       x_cur;       /* channel of the most recent VOICE message
                           * (note/gate/alg/fb/op/gm, bare = ch1); the
                           * right-inlet gate acts on this - it used to be
                           * pinned to ch1, so a help-style gate toggle
                           * keyed ch1 at its default pitch (midi 0 =
                           * 8.18 Hz sub-audio thump) under any ch2..6
                           * flow: the reported noise */
    unsigned char x_opr[6][4][6]; /* op register shadows [ch][op]: 30 40 50 60 70 80 */
    /* voice-layer portamento: `glide <ms>` arms a channel, `note` then
     * sweeps from the previous pitch to the new one (retrigger still at
     * sweep start), `slide <midi> [ms] [vel]` sweeps without a key event.
     * Geometric (midi-linear) interpolation stepped once per perform
     * block - one fnum write per block, the chip re-rates a running
     * voice on each fnum write. */
    float     x_glide[6];  /* glide time ms (0 = off, default) */
    float     x_glf[6];    /* sweep source Hz */
    float     x_glt[6];    /* sweep target Hz */
    float     x_glpos[6];  /* 0..1 position */
    float     x_glinv[6];  /* position increment per millisecond (0 = idle) */
    /* gm bank: compiled default or a runtime-loaded .wopn */
    const ym_gmpatch *x_bank;
    const signed char *x_bank_tr;
    ym_gmpatch *x_bankheap;  /* malloc'd copy when a file bank is loaded */
    signed char *x_banktrheap;
    /* Nuked-OPN2 core */
    ym3438_t  x_chip;
    double    x_rratio;    /* output samples per chip sample (fork scale) */
    double    x_rsacc;
    float     x_s0[6], x_s1[6];  /* resampler history, one slot per channel */
    /* register write queue */
    unsigned char x_wq[YMWQ][2];
    int       x_wq_rd, x_wq_cnt;
    int       x_wcd;       /* clocks until the next queued write may go */
} t_ym;

static t_class *ym_class;

static void ym_status(t_ym *x);   /* defined near ym_free */

/* ---------------------------------------------------------------- util */

static float mnote_hz(float m) {     /* midi note -> Hz (pd mtof) */
    return 8.1757989156f * powf(2.0f, m / 12.0f);
}

/* key-on/off channel field of the 0x28 data: channels 1-3 = 0,1,2,
 * channels 4-6 = 4,5,6 (the silicon skips field value 3 - channel 3 of
 * the register file does not exist).  Key-on ORs 0xf0 for all four
 * slots, key-off sends the channel field alone. */
static int chbits(int ch) {
    return ch < 3 ? ch : ch + 1;
}

/* pitch -> chip fnum/block (fc = f0 * 2^21 / chip_rate; block chosen so
 * the 11-bit fnum lands mid-range, exactly how the chip's note table
 * splits).  Same mapping the chip hardware derives from the FNUM pins. */
static void pitch_fc(t_ym *x, int ch) {
    int fc = (int)(x->x_freq[ch] * (2.0 * 1048576.0 / CHIP_RATE) + 0.5);
    int blk = 0, fn, t = fc;
    if (fc < 1) fc = 1;
    while (t >>= 1) blk++;        /* blk = bitlen(fc) - 1 */
    blk -= 10;
    if (blk < 0) blk = 0;
    if (blk > 7) blk = 7;
    fn = fc >> blk;
    if (fn > 2047) fn = 2047;
    x->x_fnum[ch] = fn;
    x->x_blk[ch] = blk;
}

/* queue one register write on a register port (A1 pin): strobe 2*port
 * carries the address, 2*port+1 the data.  port 0 = channels 1-3, port
 * 1 = channels 4-6 of the one chip. */
static void chipw_port(t_ym *x, int port, int reg, int data) {
    int w;
    Bit16s b[2];
    if (x->x_wq_cnt + 2 > YMWQ) {
        /* queue full (dsp not consuming): apply inline, in order, so
         * message bursts before dsp~ still land.  Each strobe gets its
         * 16 clocks of bus time. */
        while (x->x_wq_cnt) {
            int n;
            OPN2_Write(&x->x_chip, x->x_wq[x->x_wq_rd][0],
                       x->x_wq[x->x_wq_rd][1]);
            x->x_wq_rd = (x->x_wq_rd + 1) & (YMWQ - 1);
            x->x_wq_cnt--;
            for (n = 0; n < YMWCD; n++) OPN2_Clock(&x->x_chip, b);
        }
    }
    w = (x->x_wq_rd + x->x_wq_cnt) & (YMWQ - 1);
    x->x_wq[w][0] = (unsigned char)(port * 2);      /* address strobe */
    x->x_wq[w][1] = (unsigned char)reg;
    x->x_wq_cnt++;
    w = (x->x_wq_rd + x->x_wq_cnt) & (YMWQ - 1);
    x->x_wq[w][0] = (unsigned char)(port * 2 + 1);  /* data strobe */
    x->x_wq[w][1] = (unsigned char)data;
    x->x_wq_cnt++;
}

/* queue one register write (address strobe + data strobe, register
 * port A) */
static void chipw(t_ym *x, int reg, int data) {
    chipw_port(x, 0, reg, data);
}

/* channel-addressed register write: the register address carries the
 * within-bank channel (ch % 3), the A1 pin (port) selects the bank -
 * ch1-3 = port A offsets 0-2, ch4-6 = port B offsets 0-2, exactly the
 * encoding `chN reg` passes verbatim. */
static void chipw_ch(t_ym *x, int ch, int reg, int data) {
    chipw_port(x, ch >= 3, reg + ch % 3, data);
}

/* first voice use of a channel: flush its (default-filled) instrument
 * shadows to the chip.  The chip powers up with ALL registers zero -
 * AR 0 = envelopes can never start, so a virgin channel is mute even
 * when keyed; channels 2-6 MUST receive an instrument before a note on
 * them can sound.  Only voice messages trigger this - raw `reg` writes
 * never do, keeping the reset values raw patches depend on. */
static void ym_voice_init(t_ym *x, int ch) {
    int i;
    if (ch <= 0 || x->x_voiced[ch]) return;
    for (i = 0; i < 4; i++) {
        unsigned char *r = x->x_opr[ch][i];
        chipw_ch(x, ch, 0x30 + 4 * i, r[0]);
        chipw_ch(x, ch, 0x40 + 4 * i, r[1]);
        chipw_ch(x, ch, 0x50 + 4 * i, r[2]);
        chipw_ch(x, ch, 0x60 + 4 * i, r[3]);
        chipw_ch(x, ch, 0x70 + 4 * i, r[4]);
        chipw_ch(x, ch, 0x80 + 4 * i, r[5]);
        chipw_ch(x, ch, 0x90 + 4 * i, 0);          /* SSG-EG off */
    }
    chipw_ch(x, ch, 0xb0, (x->x_fb[ch] << 3) | x->x_alg[ch]);
    chipw_ch(x, ch, 0xb4, 0xc0);                   /* L + R out */
    x->x_voiced[ch] = 1;
}

/* write current fnum/block of one channel (A4 latch first, A0 commits) */
static void chip_fnum(t_ym *x, int ch) {
    chipw_ch(x, ch, 0xa4, (x->x_blk[ch] << 3) | ((x->x_fnum[ch] >> 8) & 7));
    chipw_ch(x, ch, 0xa0, x->x_fnum[ch] & 0xff);
}

/* recompute channel pitch from x_pitch[ch] (+transpose) and queue it */
static void pitch_update(t_ym *x, int ch) {
    x->x_freq[ch] = mnote_hz(x->x_pitch[ch] + x->x_tr[ch]);
    pitch_fc(x, ch);
    chip_fnum(x, ch);
}

/* ------------------------------------------------------------- control */

static void ym_float(t_ym *x, t_float f) {   /* inlet 1: pitch = ch1 */
    x->x_pitch[0] = f;
    pitch_update(x, 0);   /* the chip re-rates a running voice on fnum write */
}

static void ym_gate_ch(t_ym *x, int ch, t_float f) {
    int g = (f != 0);
    x->x_cur = ch;
    if (g == x->x_gate[ch]) return;
    x->x_gate[ch] = g;
    if (g) {
        ym_voice_init(x, ch);
        x->x_keyed = 1;
    }
    chipw(x, 0x28, (g ? 0xf0 : 0x00) | chbits(ch));   /* all four slots */
}

static void ym_ft1(t_ym *x, t_float f) {     /* inlet 2: gate follows the
                             * channel of the most recent voice message */
    ym_gate_ch(x, x->x_cur, f);
}

static void ym_alg_ch(t_ym *x, int ch, t_float f) {
    int v = (int)f;
    x->x_cur = ch;
    ym_voice_init(x, ch);
    if (v < 0) v = 0;
    if (v > 7) v = 7;
    x->x_alg[ch] = v;
    chipw_ch(x, ch, 0xb0, (x->x_fb[ch] << 3) | x->x_alg[ch]);
}

static void ym_alg(t_ym *x, t_float f) { ym_alg_ch(x, 0, f); }

static void ym_fb_ch(t_ym *x, int ch, t_float f) {
    int v = (int)f;
    x->x_cur = ch;
    ym_voice_init(x, ch);
    if (v < 0) v = 0;
    if (v > 7) v = 7;
    x->x_fb[ch] = v;
    chipw_ch(x, ch, 0xb0, (x->x_fb[ch] << 3) | x->x_alg[ch]);
}

static void ym_fb(t_ym *x, t_float f) { ym_fb_ch(x, 0, f); }

static void ym_dac(t_ym *x, t_float f) {
    if (f < 0) f = 0;
    if (f > 100) f = 100;
    x->x_dac = f / 100.0f;
}

/* op <1-4> <param> <value> - raw chip register values; op numbering is
 * the register page index (0/4/8/12 bytes), same space as the bank.
 * Writes land on the given channel (bare = ch1). */
static void ym_op_ch(t_ym *x, int ch, int argc, t_atom *argv) {
    int k, i;
    t_symbol *p;
    float v;
    unsigned char *r;
    x->x_cur = ch;
    ym_voice_init(x, ch);
    if (argc < 3 || argv[0].a_type != A_FLOAT || argv[1].a_type != A_SYMBOL ||
        argv[2].a_type != A_FLOAT) {
        pd_error(x, "ym2612~: op expects <1-4> <param> <value>");
        return;
    }
    k = (int)atom_getfloat(&argv[0]) - 1;
    if (k < 0 || k > 3) {
        pd_error(x, "ym2612~: operator index must be 1-4");
        return;
    }
    p = atom_getsymbol(&argv[1]);
    v = atom_getfloat(&argv[2]);
    i = (int)v;
    r = x->x_opr[ch][k];
    if (!strcmp(p->s_name, "mul")) {
        if (i < 0) i = 0;
        if (i > 15) i = 15;
        r[0] = (unsigned char)((r[0] & 0xf0) | i);
        chipw_ch(x, ch, 0x30 + 4 * k, r[0]);
    } else if (!strcmp(p->s_name, "det")) {
        if (i < 0) i = 0;
        if (i > 7) i = 7;
        r[0] = (unsigned char)((i << 4) | (r[0] & 0x0f));
        chipw_ch(x, ch, 0x30 + 4 * k, r[0]);
    } else if (!strcmp(p->s_name, "tl")) {
        if (i < 0) i = 0;
        if (i > 127) i = 127;
        r[1] = (unsigned char)i;
        chipw_ch(x, ch, 0x40 + 4 * k, r[1]);
    } else if (!strcmp(p->s_name, "rs")) {
        if (i < 0) i = 0;
        if (i > 3) i = 3;
        r[2] = (unsigned char)((i << 6) | (r[2] & 0x1f));
        chipw_ch(x, ch, 0x50 + 4 * k, r[2]);
    } else if (!strcmp(p->s_name, "ar") || !strcmp(p->s_name, "dr") ||
               !strcmp(p->s_name, "sr") || !strcmp(p->s_name, "rr")) {
        if (i < 0) i = 0;
        if (i > 31) i = 31;
        if (!strcmp(p->s_name, "rr") && i > 15) i = 15;
        switch (p->s_name[0]) {
        case 'a':
            r[2] = (unsigned char)((r[2] & 0xc0) | i);
            chipw_ch(x, ch, 0x50 + 4 * k, r[2]);
            break;
        case 'd':
            r[3] = (unsigned char)i;
            chipw_ch(x, ch, 0x60 + 4 * k, r[3]);
            break;
        case 's':
            r[4] = (unsigned char)i;
            chipw_ch(x, ch, 0x70 + 4 * k, r[4]);
            break;
        default:
            r[5] = (unsigned char)((r[5] & 0xf0) | i);
            chipw_ch(x, ch, 0x80 + 4 * k, r[5]);
            break;
        }
    } else if (!strcmp(p->s_name, "sl")) {
        if (i < 0) i = 0;
        if (i > 15) i = 15;
        r[5] = (unsigned char)((i << 4) | (r[5] & 0x0f));
        chipw_ch(x, ch, 0x80 + 4 * k, r[5]);
    } else {
        pd_error(x, "ym2612~: unknown op param %s", p->s_name);
    }
}

/* gm <1-128>: load a General MIDI Level 1 instrument preset (the current
 * bank: compiled default or a runtime-loaded .wopn, see 'bank').  The
 * bank IS raw chip register bytes: dump them 1:1 into the addressed
 * channel's registers (op page order = byte offsets 0/4/8/12); bare
 * `gm` = channel 1.  AM (LFO tremolo) and SSG-EG bits stay dropped, as
 * before. */
static void ym_gm_ch(t_ym *x, int ch, t_float f) {
    int n = (int)f;
    int i;
    const ym_gmpatch *g;
    if (n < 1 || n > 128) {
        pd_error(x, "ym2612~: gm expects 1-128 (GM instrument number)");
        return;
    }
    x->x_cur = ch;
    ym_voice_init(x, ch);
    g = &x->x_bank[n - 1];
    x->x_tr[ch] = (float)x->x_bank_tr[n - 1];   /* preset transposition */
    x->x_alg[ch] = g->alg;
    x->x_fb[ch] = g->fb;
    for (i = 0; i < 4; i++) {
        const ym_gmspec *s = &g->op[i];
        unsigned char *r = x->x_opr[ch][i];
        r[0] = (unsigned char)((s->dt << 4) | (int)s->mul); /* DT / MUL */
        r[1] = (unsigned char)s->tl;                        /* TL */
        r[2] = (unsigned char)((s->rs << 6) | s->ar);       /* KS / AR */
        r[3] = (unsigned char)s->dr;                        /* AM=0 / DR */
        r[4] = (unsigned char)s->sr;                        /* DT2=0 / SR */
        r[5] = (unsigned char)((s->sl << 4) | s->rr);       /* SL / RR */
        chipw_ch(x, ch, 0x30 + 4 * i, r[0]);
        chipw_ch(x, ch, 0x40 + 4 * i, r[1]);
        chipw_ch(x, ch, 0x50 + 4 * i, r[2]);
        chipw_ch(x, ch, 0x60 + 4 * i, r[3]);
        chipw_ch(x, ch, 0x70 + 4 * i, r[4]);
        chipw_ch(x, ch, 0x80 + 4 * i, r[5]);
        chipw_ch(x, ch, 0x90 + 4 * i, 0);                   /* SSG-EG off */
    }
    chipw_ch(x, ch, 0xb0, (x->x_fb[ch] << 3) | x->x_alg[ch]);   /* FB / ALG */
    chipw_ch(x, ch, 0xb4, 0xc0);                            /* L + R out */
    pitch_update(x, ch);   /* transpose may have changed */
}

/* bare `gm` = channel 1 (the note/GM voice) */
static void ym_gm(t_ym *x, t_float f) { ym_gm_ch(x, 0, f); }

/* voice-layer portamento.  `glide <ms>` arms the channel; the sweep
 * itself lives in the perform stepper (per-block geometric
 * interpolation, one fnum write per block).  Key semantics stay where
 * they were: note retriggers at sweep start, slide never keys. */
static void ym_glide_ch(t_ym *x, int ch, t_float f) {
    x->x_glide[ch] = f < 0.0f ? 0.0f : (f > 5000.0f ? 5000.0f : (float)f);
    x->x_cur = ch;
}

/* one sweep start: from the channel's CURRENT effective frequency to
 * the target (Hz), stepped by the perform routine.  x_freq keeps the
 * source value here - the note path's key events fire at sweep start,
 * the first fnum write of the sweep lands in the next perform block. */
static void ym_glide_start(t_ym *x, int ch, float ms, float target_hz) {
    if (ms < 1.0f) ms = 1.0f;
    if (target_hz <= 0.0f) return;
    if (x->x_freq[ch] <= 0.0f || x->x_freq[ch] == target_hz) {
        x->x_freq[ch] = target_hz;      /* no usable source: straight */
        x->x_glinv[ch] = 0.0f;
        return;
    }
    x->x_glf[ch] = x->x_freq[ch];
    x->x_glt[ch] = target_hz;
    x->x_glpos[ch] = 0.0f;
    x->x_glinv[ch] = 1.0f / ms;      /* pos/ms - an 800 ms glide
                                     * walks 0.00125 per ms */
}

static void ym_slide_ch(t_ym *x, int ch, int argc, t_atom *argv) {
    float p, ms;
    if (argc < 1 || argv[0].a_type != A_FLOAT) {
        pd_error(x, "ym2612~: slide expects <midi> [ms] [vel]");
        return;
    }
    p = atom_getfloat(&argv[0]);
    ms = x->x_glide[ch];
    if (argc >= 2 && argv[1].a_type == A_FLOAT) ms = atom_getfloat(&argv[1]);
    if (argc >= 3 && argv[2].a_type == A_FLOAT) {
        float v = atom_getfloat(&argv[2]);
        if (v < 0.0f) v = 0.0f;
        if (v > 127.0f) v = 127.0f;
        x->x_peak[ch] = v / 127.0f;   /* level rides, gate untouched */
    }
    x->x_cur = ch;
    ym_voice_init(x, ch);   /* an untouched channel must flush its
                             * instrument shadows before its fnum writes
                             * mean anything */
    x->x_pitch[ch] = p;
    if (ms <= 0.0f) {
        pitch_update(x, ch);            /* instant re-pitch */
        return;
    }
    ym_glide_start(x, ch, ms, mnote_hz(p + x->x_tr[ch]));
    if (x->x_glinv[ch] <= 0.0f) pitch_update(x, ch);
}

static void ym_note_ch(t_ym *x, int ch, int argc, t_atom *argv) {
    float p, v = 127.0f;
    if (argc < 1 || argv[0].a_type != A_FLOAT) {
        pd_error(x, "ym2612~: note expects <midi> [vel]");
        return;
    }
    p = atom_getfloat(&argv[0]);
    if (argc >= 2 && argv[1].a_type == A_FLOAT) v = atom_getfloat(&argv[1]);
    if (v < 0) v = 0;
    if (v > 127) v = 127;
    if (v <= 0) {
        /* MIDI note-off: release the voice through the gate fade + the
         * chip's rr stage.  Pitch and peak stay untouched so the tail
         * rings at the note's own level - treating vel 0 as a peak-0
         * key-on hard-muted every note-off (clicks, no release tails,
         * every preset dulled). */
        x->x_gate[ch] = 0;
        chipw(x, 0x28, chbits(ch));
        return;
    }
    x->x_cur = ch;
    ym_voice_init(x, ch);
    x->x_peak[ch] = v / 127.0f;
    /* a note IS a key-on: open the channel gate too, otherwise note-driven
     * patches stay silent (the gate inlet only opens ggain on its own) */
    x->x_gate[ch] = 1;
    x->x_pitch[ch] = p;   /* THE note's pitch: pitch_update recomputes the
                           * fnum pair from x_pitch - forgetting this line
                           * played every note at the object's default pitch */
    if (x->x_glide[ch] > 0.0f) {
        /* portamento: sweep from the previous pitch (x_freq holds it
         * until the first perform step); the key events below still fire
         * at sweep START - the note sounds while it slides */
        ym_glide_start(x, ch, x->x_glide[ch], mnote_hz(p + x->x_tr[ch]));
        if (x->x_glinv[ch] <= 0.0f) pitch_update(x, ch);
    } else {
        pitch_update(x, ch);
    }
    chipw(x, 0x28, chbits(ch));   /* key off first: a note always
                                   * retriggers, even while the gate is
                                   * already open */
    x->x_keyed = 1;
    chipw(x, 0x28, 0xf0 | chbits(ch));
}

/* bare `note` = channel 1 */
static void ym_note(t_ym *x, int argc, t_atom *argv) { ym_note_ch(x, 0, argc, argv); }

/* ------------------------------------------------------- bank loading */

/* free a runtime-loaded bank (compiled default needs nothing) */
static void ym_bank_clear(t_ym *x) {
    if (x->x_bankheap) {
        freebytes(x->x_bankheap, 128 * sizeof(ym_gmpatch));
        x->x_bankheap = 0;
    }
    if (x->x_banktrheap) {
        freebytes(x->x_banktrheap, 128 * sizeof(signed char));
        x->x_banktrheap = 0;
    }
    x->x_bank = (const ym_gmpatch *)ym_gm_bank;
    x->x_bank_tr = (const signed char *)ym_gm_tr;
}

/* parse a WOPN image into 128 fresh rows; returns 1 on success (rows in
 * *bkp/*trp, heap-owned) or 0 with a console error.  Two layouts are
 * accepted, both with RAW CHIP REGISTER bytes (same unpack as the
 * generator): v2 "WOPN2-B2NK" = 16-byte header + 34-byte bank
 * descriptors + 69-byte instrument entries (32 name, BE i16 note
 * offset, key, FB/ALG, LFO sens, 4 ops x 7 bytes, 2+2 delay bytes);
 * v1 "WOPN2-BANK" = 14-byte header + 1 filler byte + 65-byte entries
 * (same fields, no descriptors, no delays).  Only the melodic bank 0
 * is taken - ym2612~ is a melodic voice. */
static int ym_bank_parse(t_ym *x, const unsigned char *d, unsigned long len) {
    int v2, nmel, nperc, ent, base;
    unsigned long need;
    ym_gmpatch *bk;
    signed char *tr;
    int n, l;
    if (len >= 18 && !memcmp(d, "WOPN2-B2NK\x00", 11)) {
        v2 = 1;
        nmel = (d[13] << 8) | d[14];
        nperc = (d[15] << 8) | d[16];
        base = 18 + 34 * (nmel + nperc);
        ent = 69;
    } else if (len >= 17 && !memcmp(d, "WOPN2-BANK\x00", 11)) {
        v2 = 0;
        nmel = (d[11] << 8) | d[12];
        nperc = (d[13] << 8) | d[14];
        base = 16;
        ent = 65;
    } else {
        pd_error(x, "ym2612~: bank: not a WOPN file (magic mismatch)");
        return 0;
    }
    need = (unsigned long)base + 128UL * ent;
    if (nmel < 1 || len < need) {
        pd_error(x, "ym2612~: bank: truncated or has no melodic bank "
                    "(nmel %d, %lu bytes, need %lu)", nmel, len, need);
        return 0;
    }
    bk = (ym_gmpatch *)getbytes(128 * sizeof(ym_gmpatch));
    tr = (signed char *)getbytes(128 * sizeof(signed char));
    if (!bk || !tr) {
        if (bk) freebytes(bk, 128 * sizeof(ym_gmpatch));
        if (tr) freebytes(tr, 128 * sizeof(signed char));
        pd_error(x, "ym2612~: bank: out of memory");
        return 0;
    }
    for (n = 0; n < 128; n++) {
        const unsigned char *e = d + base + (unsigned long)n * ent;
        int off = (e[32] << 8) | e[33];
        int fbalg = e[35];
        bk[n].alg = fbalg & 7;
        bk[n].fb = (fbalg >> 3) & 7;
        tr[n] = (signed char)(off > 32767 ? off - 65536 : off);
        for (l = 0; l < 4; l++) {
            const unsigned char *o = e + 37 + l * 7;
            ym_gmspec *s = &bk[n].op[l];
            s->mul = (float)(o[0] & 15);
            s->dt = (o[0] >> 4) & 7;
            s->tl = o[1] & 0x7f;
            s->ar = o[2] & 31;
            s->rs = (o[2] >> 6) & 3;
            s->dr = o[3] & 31;
            s->sr = o[4] & 31;
            s->sl = (o[5] >> 4) & 15;
            s->rr = o[5] & 15;
        }
    }
    ym_bank_clear(x);
    x->x_bankheap = bk;
    x->x_banktrheap = tr;
    x->x_bank = bk;
    x->x_bank_tr = tr;
    return 1;
}

/* File lookup with no canvas dependency. canvas_open() dereferences the
 * canvas (gl_env owner-chain walk), and canvas_getcurrent() in the libpd
 * runtime is a "pd"-symbol binding lookup that yields stale pointers
 * under the app's patch open/close churn - measured SIGSEGV inside
 * canvas_path_iterate on device (0.17.69). open_via_path() only walks
 * the string search path (stable ABI); the app keeps the current patch's
 * directory and files/ymbanks on it. Shared with vgm_tilde.c. */
int ympp_findfile(const char *name, char *full, unsigned int n) {
    char dirbuf[MAXPDSTRING], *base = 0;
    int fd;
    if (!name || !name[0]) return 0;
    fd = open_via_path("", name, "", dirbuf, &base, MAXPDSTRING, 1);
    if (fd <= 0) return 0;  /* pd never hands out fds 0-2 on success */
    sys_close(fd);          /* only the location is needed; reopen below */
    snprintf(full, n, "%s/%s", dirbuf, base ? base : name);
    return 1;
}

/* bank <name.wopn|default>: swap the whole GM table at message rate.
 * The file resolves through pd's search path (the app registers its
 * bundled-bank folder and the current patch's directory). */
static void ym_bank(t_ym *x, t_symbol *s) {
    char full[MAXPDSTRING];
    int rc;
    FILE *f;
    unsigned char *buf = 0;
    unsigned long len, got;
    if (!s || !s->s_name || !s->s_name[0]) {
        post("ym2612~: bank is '%s' (%s)",
             x->x_bankheap ? "runtime file" : "compiled default",
             x->x_bankheap ? "use 'bank default' to go back" : "loaded");
        return;
    }
    if (!strcmp(s->s_name, "default")) {
        ym_bank_clear(x);
        post("ym2612~: bank: compiled default restored");
        return;
    }
    rc = ympp_findfile(s->s_name, full, MAXPDSTRING);
    if (!rc) {
        pd_error(x, "ym2612~: bank: '%s' not found (pd search path)",
                 s->s_name);
        return;
    }
    f = fopen(full, "rb");
    if (!f) {
        pd_error(x, "ym2612~: bank: cannot open '%s'", full);
        return;
    }
    fseek(f, 0, SEEK_END);
    len = (unsigned long)ftell(f);
    fseek(f, 0, SEEK_SET);
    buf = (unsigned char *)getbytes(len ? len : 1);
    got = buf && len ? fread(buf, 1, len, f) : 0;
    fclose(f);
    if (!buf || got != len) {
        if (buf) freebytes(buf, len ? len : 1);
        pd_error(x, "ym2612~: bank: read failed on '%s'", s->s_name);
        return;
    }
    if (ym_bank_parse(x, buf, len))
        post("ym2612~: bank '%s' loaded: 128 GM presets, "
             "fb/alg/op bytes verbatim", s->s_name);
    freebytes(buf, len ? len : 1);
}

/* raw <1/0>: vgm player mode - pin gate and peak (the VGM's own
 * registers own the level), and accept `reg <addr> <data>` writes.
 * Opening gate/peak covers ALL six channels, exactly like the old
 * global voice fields did. */
static void ym_raw(t_ym *x, t_float f) {
    int c;
    x->x_rawmode = (f != 0);
    if (x->x_rawmode) {
        for (c = 0; c < 6; c++) {
            x->x_gate[c] = 1;       /* the 20ms fade still opens the voice */
            x->x_peak[c] = 1.0f;
        }
    }
}

/* reg <addr> <data>: one raw chip-bus write, verbatim (the vgm player
 * pre-translates port/channel addressing per outlet). */
static void ym_reg(t_ym *x, t_symbol *s, int argc, t_atom *argv) {
    (void)s;
    int a, d;
    if (argc < 2) return;
    a = (int)atom_getfloat(&argv[0]) & 0xff;
    d = (int)atom_getfloat(&argv[1]) & 0xff;
    if (a >= 0x30 && a <= 0x9f && (a & 3) == 3) return;  /* no channel 3 */
    if (a == 0x28 && (d & 0xf0)) x->x_keyed = 1;
    chipw(x, a, d);
}

/* ch-addressed raw write.  ch is 0-based: 0..2 = register port A
 * channels 1-3, 3..5 = port B channels 4-6 (Nuked bus strobes 2/3 carry
 * the A1 pin).  Register bytes pass verbatim - one Nuked core plays all
 * six channels, no per-voice re-addressing anywhere.  Key-on (0x28)
 * always rides the port-A strobes: its data bit 2 selects the chip
 * port, as on silicon. */
static void ym_reg_ch(t_ym *x, int ch, int argc, t_atom *argv) {
    int a, d, c;
    if (argc < 2) return;
    if (!x->x_rawmode) {
        /* register writes imply raw: the chip's own envelopes own the
         * sound from here, so pin gate/peak open (before 0.17.78 a
         * manual `raw 1` was required before anything could be heard) */
        x->x_rawmode = 1;
        for (c = 0; c < 6; c++) {
            x->x_gate[c] = 1;
            x->x_peak[c] = 1.0f;
        }
    }
    a = (int)atom_getfloat(&argv[0]) & 0xff;
    d = (int)atom_getfloat(&argv[1]) & 0xff;
    if (a >= 0x30 && a <= 0x9f && (a & 3) == 3) return;  /* no channel 3 */
    if (a == 0x28) {
        if (d & 0xf0) x->x_keyed = 1;
        chipw_port(x, 0, a, d);
        return;
    }
    if (a >= 0x2a && a <= 0x2b) {   /* DAC enable/data: port A only */
        chipw_port(x, 0, a, d);
        return;
    }
    if (ch < 3) {
        chipw_port(x, 0, a, d);
    } else {
        chipw_port(x, 1, a, d);     /* register port B: channels 4-6 */
    }
}

/* anything on inlet 1: alg / fb / dac / op / note / gate / list / chN.
 * `chN <sub>` (N = 1..6) addresses a channel directly: note / gate /
 * alg / fb / op / gm become THAT channel's voice controls, reg stays
 * the channel-addressed raw register write.  dac / raw / bank are
 * object-global settings - the chN prefix is accepted but meaningless,
 * they dispatch to the bare handler. */
static void ym_anything(t_ym *x, t_symbol *s, int argc, t_atom *argv) {
    const char *name = s->s_name;
    if (name[0] == 'c' && name[1] == 'h' && name[2] >= '1' && name[2] <= '6'
        && name[3] == 0 && argc >= 1) {
        int ch = name[2] - '1';
        if (argc >= 2 && argv[0].a_type == A_SYMBOL) {
            t_symbol *sub = atom_getsymbol(&argv[0]);
            t_atom *av = argv + 1;
            int na = argc - 1;
            if (!strcmp(sub->s_name, "reg")) {
                /* chN reg <a> <d>: channel-addressed raw write (Nuked plays
                 * all six channels of the one chip); bare `reg` stays the
                 * ch-1 compat path */
                ym_reg_ch(x, ch, na, av);
            } else if (!strcmp(sub->s_name, "note")) {
                ym_note_ch(x, ch, na, av);
            } else if (!strcmp(sub->s_name, "glide")) {
                if (na >= 1 && av[0].a_type == A_FLOAT)
                    ym_glide_ch(x, ch, atom_getfloat(av));
            } else if (!strcmp(sub->s_name, "slide")) {
                ym_slide_ch(x, ch, na, av);
            } else if (!strcmp(sub->s_name, "gate")) {
                if (na >= 1 && av[0].a_type == A_FLOAT)
                    ym_gate_ch(x, ch, atom_getfloat(av));
            } else if (!strcmp(sub->s_name, "alg")) {
                if (na >= 1 && av[0].a_type == A_FLOAT)
                    ym_alg_ch(x, ch, atom_getfloat(av));
            } else if (!strcmp(sub->s_name, "fb")) {
                if (na >= 1 && av[0].a_type == A_FLOAT)
                    ym_fb_ch(x, ch, atom_getfloat(av));
            } else if (!strcmp(sub->s_name, "op")) {
                ym_op_ch(x, ch, na, av);
            } else if (!strcmp(sub->s_name, "gm")) {
                if (na >= 1 && av[0].a_type == A_FLOAT)
                    ym_gm_ch(x, ch, atom_getfloat(av));
            } else if (!strcmp(sub->s_name, "dac") ||
                       !strcmp(sub->s_name, "raw") ||
                       !strcmp(sub->s_name, "bank")) {
                ym_anything(x, sub, na, av);
            } else {
                pd_error(x, "ym2612~: unknown channel message ch%d %s",
                         ch + 1, sub->s_name);
            }
            return;
        }
    }
    if (!strcmp(name, "alg")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT) ym_alg(x, atom_getfloat(argv));
    } else if (!strcmp(name, "fb")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT) ym_fb(x, atom_getfloat(argv));
    } else if (!strcmp(name, "dac")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT) ym_dac(x, atom_getfloat(argv));
    } else if (!strcmp(name, "op")) {
        ym_op_ch(x, 0, argc, argv);
    } else if (!strcmp(name, "gm")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT) ym_gm(x, atom_getfloat(argv));
    } else if (!strcmp(name, "bank")) {
        if (argc >= 1 && argv[0].a_type == A_SYMBOL) ym_bank(x, atom_getsymbol(&argv[0]));
        else ym_bank(x, 0);
    } else if (!strcmp(name, "raw")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT) ym_raw(x, atom_getfloat(argv));
    } else if (!strcmp(name, "reg")) {
        ym_reg(x, s, argc, argv);
    } else if (!strcmp(name, "note")) {
        ym_note(x, argc, argv);
    } else if (!strcmp(name, "glide")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT)
            ym_glide_ch(x, 0, atom_getfloat(argv));
    } else if (!strcmp(name, "slide")) {
        ym_slide_ch(x, 0, argc, argv);
    } else if (!strcmp(name, "status")) {
        ym_status(x);
    } else if (!strcmp(name, "gate")) {
        if (argc >= 1 && argv[0].a_type == A_FLOAT) ym_ft1(x, atom_getfloat(argv));
    } else if (!strcmp(name, "list")) {
        /* OSC bridges deliver "alg 7", "note 60" ... as lists; re-dispatch
         * symbol-first lists as the named message, numeric lists stay
         * pitch [+ velocity] */
        if (argc >= 2 && argv[0].a_type == A_SYMBOL) {
            ym_anything(x, atom_getsymbol(&argv[0]), argc - 1, argv + 1);
        } else if (argc >= 1 && argv[0].a_type == A_FLOAT) {
            if (argc >= 2 && argv[1].a_type == A_FLOAT) {
                float v = atom_getfloat(&argv[1]);
                if (v < 0) v = 0;
                if (v > 127) v = 127;
                x->x_peak[0] = v / 127.0f;
            }
            ym_float(x, atom_getfloat(argv));
        }
    } else {
        pd_error(x, "ym2612~: unknown message %s", name);
    }
}

/* ---------------------------------------------------------------- dsp */

/* one chip sample: 24 bus clocks; one queued register write per 16
 * clocks rides along so message-rate bursts land inside the audio,
 * without a hole.  Output = frame-aligned direct read of channel 0's
 * accumulator: in ym2612 mode the mol pin runs a serial-DAC protocol -
 * only the (cycles&3)==3 clock carries the full-precision value, the
 * other clocks emit out>>8 sign stubs (+1 bias on silent channels) -
 * so summing the pins mixes protocol artifacts into the output (DC
 * pedestal + cross-channel intermod).  ch_out[0] is the value the
 * silicon's DAC unit itself consumes; it latches at the channel-0 slot
 * (cycles 12-15), phase-aligned with the pin's full-value pulse. */
static void ym_gen(t_ym *x, float *ch) {
    Bit16s b[2];
    int i, c;
    for (i = 0; i < 24; i++) {
        if (x->x_wcd > 0) x->x_wcd--;
        else if (x->x_wq_cnt > 0) {
            x->x_wcd = YMWCD;
            OPN2_Write(&x->x_chip, x->x_wq[x->x_wq_rd][0],
                       x->x_wq[x->x_wq_rd][1]);
            x->x_wq_rd = (x->x_wq_rd + 1) & (YMWQ - 1);
            x->x_wq_cnt--;
        }
        OPN2_Clock(&x->x_chip, b);
    }
    /* one chip plays all six channels: every outlet carries its own
     * accumulator (each channel's own DAC-unit value).  GM patches only
     * key channel 1 - channels 2-6 sit at reset with ch_out 0, so the
     * GM output is bit-identical to the old channel-1-only read.
     * (The bus DAC rides the mol path, not ch_out[6]; PCM songs take it
     * from vgm~'s DAC outlet.) */
    for (c = 0; c < 6; c++)
        ch[c] = (float)x->x_chip.ch_out[c] * OUTSCALE;
}

static t_int *ym_perform(t_int *w) {
    t_ym *x = (t_ym *)(w[1]);
    t_sample **outv = (t_sample **)w[2];
    t_sample *out[7];
    int n = (int)(w[3]);
    int k, s;
    float gstep[6];
    for (k = 0; k < 7; k++) out[k] = outv[k];
    for (k = 0; k < 6; k++)
        gstep[k] = (x->x_gate[k] ? 1.0f : -1.0f) / (0.02f * x->x_sr + 1.0f);
    /* portamento stepper, once per block: geometric interpolation
     * toward the target (midi-linear), one fnum write per block
     * (~1.3 ms) - the chip re-rates a running voice on each fnum write */
    {
        int c;
        float dms = (float)n / x->x_sr * 1000.0f;   /* block time in ms */
        for (c = 0; c < 6; c++) {
            if (x->x_glinv[c] <= 0.0f) continue;
            x->x_glpos[c] += x->x_glinv[c] * dms;
            if (x->x_glpos[c] >= 1.0f) {
                x->x_glpos[c] = 1.0f;
                x->x_glinv[c] = 0.0f;
                x->x_freq[c] = x->x_glt[c];
            } else {
                x->x_freq[c] = x->x_glf[c]
                    * powf(x->x_glt[c] / x->x_glf[c], x->x_glpos[c]);
            }
            pitch_fc(x, c);
            chip_fnum(x, c);
        }
    }
    for (s = 0; s < n; s++) {
        float ch[6];
        float frac, sum = 0.0f;
        int c;
        /* channel gates, one fade per channel */
        for (c = 0; c < 6; c++) {
            x->x_ggain[c] += gstep[c];
            if (x->x_ggain[c] < 0) x->x_ggain[c] = 0;
            if (x->x_ggain[c] > 1) x->x_ggain[c] = 1;
        }
        if (!x->x_keyed) {
            /* No key-on has ever reached this voice: the chip sits at
             * reset (all envelopes at bottom, ch_out 0), so rendering
             * would produce exactly zero.  Skip the 24 OPN2_Clock per
             * sample - output-identical, and six idle vgm voices cost
             * 6x the chip budget, which xruns the audio thread on
             * device (measured 0.17.75: underruns + harsh glitches). */
            for (c = 0; c < 7; c++) out[c][s] = 0;
            continue;
        }
        /* resample chip rate -> pd rate (fork's linear interpolator);
         * all channels share the chip sample instants, so one
         * accumulator drives everything - and linear interpolation is
         * linear, so the sum of the interpolated channels IS the old
         * interpolated-sum output. */
        x->x_rsacc += 1.0;
        while (x->x_rsacc >= x->x_rratio) {
            x->x_rsacc -= x->x_rratio;
            for (c = 0; c < 6; c++) x->x_s0[c] = x->x_s1[c];
            ym_gen(x, x->x_s1);
        }
        frac = (float)(x->x_rsacc / x->x_rratio);
        for (c = 0; c < 6; c++) {
            float v = x->x_s0[c] + (x->x_s1[c] - x->x_s0[c]) * frac;
            v *= x->x_peak[c] * x->x_ggain[c];
            if (x->x_dac > 0) {
                float y = roundf(v * 256.0f) / 256.0f;
                y += 0.012f * x->x_dac * expf(-64.0f * (v + 0.5f) * (v + 0.5f));
                v = y;
            }
            ch[c] = v;
            out[c + 1][s] = v;
            sum += v;
        }
        /* outlet 0 = the chip mix.  No +-1 clip (see header): the
         * silicon's accumulators are hardware-bounded, the sum is not,
         * and the console amp's clip belongs to the patch downstream. */
        out[0][s] = sum;
    }
    return (w + 4);
}

static void ym_dsp(t_ym *x, t_signal **sp) {
    int k;
    x->x_sr = sp[0]->s_sr > 1.0f ? sp[0]->s_sr : 48000.0f;
    x->x_rratio = (144.0 * x->x_sr) / CHIP_CLOCK;
    for (k = 0; k < 7; k++) x->x_outv[k] = sp[k]->s_vec;
    dsp_add(ym_perform, 3, x, x->x_outv, sp[0]->s_n);
}

/* ------------------------------------------------------------ lifecycle */

/* defaults land on channel 1 only - channels 2-6 keep the chip's RESET
 * register values, exactly as before the per-channel voices existed
 * (raw patches depend on those reset values).  Their SHADOWS still
 * carry the default instrument, so a lazy ym_voice_init on first voice
 * use sounds like the factory voice. */
static void ym_new_defaults(t_ym *x) {
    int i, c;
    for (c = 0; c < 6; c++) {
        x->x_alg[c] = 0;
        x->x_fb[c] = 0;
        for (i = 0; i < 4; i++) {
            unsigned char *r = x->x_opr[c][i];
            r[0] = 0x01;            /* DT 0 / MUL 1 */
            r[1] = (unsigned char)((i < 3) ? 16 : 0);   /* TL */
            r[2] = 0x1f;            /* KS 0 / AR 31 */
            r[3] = 12;              /* DR 12 */
            r[4] = 5;               /* SR 5 */
            r[5] = 0x87;            /* SL 8 / RR 8 */
        }
    }
    for (i = 0; i < 4; i++) {   /* ch1's instrument goes to the chip now */
        unsigned char *r = x->x_opr[0][i];
        chipw(x, 0x30 + 4 * i, r[0]);
        chipw(x, 0x40 + 4 * i, r[1]);
        chipw(x, 0x50 + 4 * i, r[2]);
        chipw(x, 0x60 + 4 * i, r[3]);
        chipw(x, 0x70 + 4 * i, r[4]);
        chipw(x, 0x80 + 4 * i, r[5]);
        chipw(x, 0x90 + 4 * i, 0);
    }
    chipw(x, 0xb0, 0x00);       /* FB 0 / ALG 0 */
    chipw(x, 0xb4, 0xc0);       /* L + R out */
    pitch_update(x, 0);
}

static void ym_free(t_ym *x) {
    ym_bank_clear(x);
}

/* per-channel state dump to the console (the opl3~/nes~ convention) -
 * fn/blk are the chip-domain pitch the channel currently sounds */
static void ym_status(t_ym *x) {
    int c;
    post("ym2612~ status: keyed=%d rawmode=%d sr=%.0f dac=%.2f",
         x->x_keyed, x->x_rawmode, (double)x->x_sr, (double)x->x_dac);
    for (c = 0; c < 6; c++) {
        post("  ch%d voiced=%d gate=%d ggain=%.3f peak=%.2f pitch=%.1f "
             "fn=%d blk=%d glide=%.0f ms glidepos=%.2f alg=%d fb=%d",
             c + 1, x->x_voiced[c], x->x_gate[c], (double)x->x_ggain[c],
             (double)x->x_peak[c], (double)x->x_pitch[c],
             x->x_fnum[c], x->x_blk[c], (double)x->x_glide[c],
             (double)x->x_glpos[c], x->x_alg[c], x->x_fb[c]);
    }
}

static void *ym_new(void) {
    t_ym *x = (t_ym *)pd_new(ym_class);
    int c;
    x->x_sr = 48000.0f;
    x->x_rawmode = 0;
    x->x_keyed = 0;
    x->x_cur = 0;
    x->x_voiced[0] = 1;   /* ch1's instrument is written at creation */
    for (c = 1; c < 6; c++) x->x_voiced[c] = 0;
    x->x_bank = (const ym_gmpatch *)ym_gm_bank;
    x->x_bank_tr = (const signed char *)ym_gm_tr;
    x->x_bankheap = 0;
    x->x_banktrheap = 0;
    x->x_dac = 0.0f;
    x->x_rratio = (144.0 * 48000.0) / CHIP_CLOCK;
    x->x_rsacc = 0.0;
    for (c = 0; c < 6; c++) {
        x->x_pitch[c] = 0.0f;
        x->x_freq[c] = 0.0f;
        x->x_tr[c] = 0.0f;
        x->x_peak[c] = 1.0f;
        x->x_gate[c] = 0;
        x->x_ggain[c] = 0.0f;
        x->x_alg[c] = 0;
        x->x_fb[c] = 0;
        x->x_fnum[c] = 0;
        x->x_blk[c] = 0;
        x->x_glide[c] = 0.0f;
        x->x_glf[c] = x->x_glt[c] = x->x_glpos[c] = x->x_glinv[c] = 0.0f;
        {   int i, j;
            for (i = 0; i < 4; i++)
                for (j = 0; j < 6; j++) x->x_opr[c][i][j] = 0;
        }
    }
    {   int i;
        for (i = 0; i < 6; i++) x->x_s0[i] = x->x_s1[i] = 0.0f;
    }
    x->x_wq_rd = 0;
    x->x_wq_cnt = 0;
    x->x_wcd = 0;
    memset(&x->x_chip, 0, sizeof(x->x_chip));
    OPN2_SetChipType(ym3438_mode_ym2612);
    OPN2_Reset(&x->x_chip);
    ym_new_defaults(x);
    {   /* outlet 0 first = leftmost: the chip mix; 1..6 = channels 1..6 */
        int i;
        for (i = 0; i < 7; i++)
            x->x_out[i] = outlet_new(&x->obj, &s_signal);
    }
    x->x_gatein = inlet_new(&x->obj, &x->obj.ob_pd, &s_float, gensym("ft1"));
    return (void *)x;
}

void ym2612_tilde_setup(void) {
    ym_class = class_new(gensym("ym2612~"), (t_newmethod)ym_new,
                         (t_method)ym_free, sizeof(t_ym), 0, A_NULL);
    class_addfloat(ym_class, ym_float);
    class_addmethod(ym_class, (t_method)ym_ft1, gensym("ft1"), A_FLOAT, A_NULL);
    class_addanything(ym_class, ym_anything);
    class_addmethod(ym_class, (t_method)ym_dsp, gensym("dsp"), A_CANT, A_NULL);
}
